// The seed catalog seen through one store: its price, its stock, its delivery.
// Facts come from catalog/catalog.json (generated by catalog/seed.py); live stock
// comes from the store's SQLite database.
import catalogData from "./data/catalog.json";
import type { StoreKey } from "./store";

export type Category = "trail" | "road";

export interface SeedModel {
  id: string;
  slug: string;
  name: string;
  brand: string;
  category: Category;
  tagline_es: string;
  description_es: string;
  color_es: string;
  sizes: string[];
  image: string;
  pulso_image: string;
  stores: Record<
    StoreKey,
    {
      price_usd: number;
      stock: Record<string, number>;
      shipping_usd: number;
      handling_business_days: [number, number];
      transit_business_days: [number, number];
    }
  >;
}

export interface Variant {
  id: string; // stable across stores: "<model id>-<size>"
  sku: string; // store specific
  size: string;
  stock: number;
}

export interface Product {
  id: string;
  slug: string;
  name: string;
  brand: string;
  category: Category;
  categoryLabel: string;
  tagline: string;
  description: string;
  color: string;
  image: string;
  pulsoImage: string;
  priceCents: number;
  currency: "USD";
  variants: Variant[];
  shipping: {
    rateCents: number;
    country: string;
    handlingDays: [number, number];
    transitDays: [number, number];
  };
}

export const CATEGORY_LABEL: Record<Category, string> = { trail: "Trail", road: "Ruta" };

export const seedModels = (catalogData as unknown as { models: SeedModel[] }).models;
export const shipsTo = (catalogData as unknown as { ships_to: string }).ships_to;

export function variantId(modelId: string, size: string): string {
  return `${modelId}-${size}`;
}

export function skuFor(store: StoreKey, modelId: string, size: string): string {
  return `${store === "kilometro" ? "KM" : "PL"}-${modelId}-${size}`;
}

/** Initial stock rows for a store: one per (model, size). */
export function seedStock(store: StoreKey): { variantId: string; productId: string; size: string; qty: number }[] {
  return seedModels.flatMap((m) =>
    m.sizes.map((size) => ({
      variantId: variantId(m.id, size),
      productId: m.id,
      size,
      qty: m.stores[store].stock[size] ?? 0,
    })),
  );
}

export function toProduct(m: SeedModel, store: StoreKey, stockOf: (variantId: string) => number): Product {
  const s = m.stores[store];
  return {
    id: m.id,
    slug: m.slug,
    name: m.name,
    brand: m.brand,
    category: m.category,
    categoryLabel: CATEGORY_LABEL[m.category],
    tagline: m.tagline_es,
    description: m.description_es,
    color: m.color_es,
    image: `/${m.image}`,
    pulsoImage: `/${m.pulso_image}`,
    priceCents: Math.round(s.price_usd * 100),
    currency: "USD",
    variants: m.sizes.map((size) => ({
      id: variantId(m.id, size),
      sku: skuFor(store, m.id, size),
      size,
      stock: stockOf(variantId(m.id, size)),
    })),
    shipping: {
      rateCents: Math.round(s.shipping_usd * 100),
      country: shipsTo,
      handlingDays: s.handling_business_days,
      transitDays: s.transit_business_days,
    },
  };
}

export function formatUsd(cents: number): string {
  return `${(cents / 100).toFixed(cents % 100 === 0 ? 0 : 2)} USD`;
}

/** Human wording of the published delivery time, e.g. "1 día hábil". */
export function deliveryLabel(p: Product): string {
  const min = p.shipping.handlingDays[0] + p.shipping.transitDays[0];
  const max = p.shipping.handlingDays[1] + p.shipping.transitDays[1];
  const days = min === max ? `${max}` : `${min} a ${max}`;
  return `${days} ${max === 1 ? "día hábil" : "días hábiles"}`;
}
